n("תדהר", "תדהר הוא שמו של עץ שמוזכר בספר ישעיהו, ברשימה של עצים שיצמחו במדבר. לא ברור איזה עץ הוא, ויש שמזהים אותו עם האשור או עם עץ אחר שגדל בהרים. השם ניתן גם לבנים וגם לבנות, והוא מביא תמונה של צמיחה במקום יבש.", [])
n("ולדימיר", "ולדימיר הוא שם סלאבי עתיק שבנוי משתי מילים, ולד, שלטון, ומיר, עולם או שלום. ברוסית ובאוקראינית השם נפוץ מאוד, ומוכרת גם צורת החיבה וולודיה. השם הגיע לארץ עם העלייה מברית המועצות.", [])
n("יבגני", "יבגני הוא שם רוסי שבא מהשם היווני אאוגניוס, שפירושו אציל או בן למשפחה טובה. ברוסית מוכרת גם צורת החיבה ז׳ניה, ובאנגלית הצורה יוג׳ין. מוכרת גם צורת הנקבה יבגניה.", ["יבגניה"])
n("אתי", "אתי הוא צורת חיבה של אסתר, ובשפות של אירופה גם של שמות כמו הנרייטה. בעברית השם נשמע גם כמו המילה איתי, עם אלוהים. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["אסתר"])
n("תומס", "תומס הוא שם בינלאומי שבא מהארמית, מהמילה תאומא, תאום. השם נפוץ מאוד בשפות של אירופה, ובצרפתית הוא נכתב תומא. בעברית המילה תאום באה מאותו שורש.", [])
n("ירמיהו", "ירמיהו הוא שמו של אחד מגדולי הנביאים, שחי בימי חורבן הבית הראשון, וספר שלם בתנ״ך נקרא על שמו. השם בנוי מהשורש ר־ו־ם ומהסיומת יהו, ופירושו ה׳ ירומם. בעברית מוכרת גם הצורה הקצרה ירמיה.", ["ירמי"])
n("אוראן", "אוראן הוא שם עברי חדש, וכנראה הוא בא מהמילה אור, עם סיומת שמופיעה גם בשמות כמו אוריאן. השם ניתן גם לבנים וגם לבנות. בטורקית יש שם בצליל דומה, אורהאן, שמקורו אחר.", ["אוריאן"])
n("אלבי", "אלבי הוא שם עברי חדש, וכנראה הוא בנוי מהמילים אל ובי, ופירושו אלוהים בתוכי. באנגלית יש שם בצליל זהה, שמקורו אחר. השם נדיר, וניתן גם לבנים וגם לבנות.", [])
n("אשד", "אשד היא מילה עתיקה למפל מים, ולמקום שבו מים זורמים במורד. בעברית החדשה אשד הוא שם של מפלים, כמו בשמורות שבצפון הארץ. כשם, אשד מביא תמונה של מים חזקים וזורמים.", [])
n("פליאה", "פליאה היא מילה עברית להתפעלות ולתמיהה מול דבר מופלא. מאותו שורש, פ־ל־א, באות המילים פלא ונפלא. כשם, פליאה מביא את הרעיון של עולם מלא הפתעות.", ["פלא"])
n("אומה", "אומה היא מילה עברית לעם, קבוצה גדולה של אנשים שיש להם היסטוריה ושפה משותפות. בהודית ובסנסקריט אומה הוא שם של אלה, ובשפות אחרות יש לשם מקורות נוספים. השם ניתן בעיקר לבנות.", [])
n("מרי", "מרי היא הצורה האנגלית והצרפתית של השם מרים, שהגיע לאירופה דרך היוונית והלטינית. השם נפוץ מאוד בעולם, ובכל שפה הוא נשמע מעט אחרת. בעברית המילה מרי פירושה גם התנגדות ומרד.", ["מרים", "מריה"])
n("חלי", "חלי היא מילה עתיקה לתכשיט שתולים על הצוואר, והיא מופיעה בספר משלי. מאותה מילה באה המילה חליה, קישוט. כשם, חלי מביא את הרעיון של דבר יקר ויפה, והוא ניתן בעיקר לבנות.", [])
n("לנה", "לנה הוא שם בינלאומי, וכנראה הוא קיצור של שמות כמו הלנה ומגדלנה. השם נפוץ מאוד בגרמנית, ברוסית ובשפות הסקנדינביות. ברוסיה לנה היא גם שמו של נהר גדול בסיביר.", ["לינה"])
n("שטרנא", "שטרנא הוא שם ביידיש, שבא מהמילה היידית שטערן, כוכב, שקרובה למילה הגרמנית שטרן. מוכרת גם הצורה סטערנא. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", [])
n("לואן", "לואן הוא שם חדש, וכנראה הוא צירוף של הצלילים לו ואן, שנשמעים רכים ונעימים. בצרפתית יש שם בצליל דומה, לואן, שמקורו קשור לשם לואי. השם ניתן בעיקר לבנות.", [])
n("רוברט", "רוברט הוא שם בינלאומי שבא מגרמנית עתיקה, ובנוי משתי מילים, תהילה ומאיר, ופירושו תהילה מאירה. השם נפוץ בשפות רבות, ובאיטלקית ובשפה הספרדית הוא נשמע רוברטו. באנגלית מוכרות צורות החיבה בוב ורוב.", ["רוברטו"])
n("אבלין", "אבלין הוא שם בינלאומי, וכנראה הוא כתיב אחר של אוולין, שם שמקורו נורמני. השם נפוץ באנגלית ובצרפתית. בעברית הוא נשמע גם קרוב לאביב ולאבל, אבל אין קשר בין המילים.", ["אוולין"])
n("ניבר", "ניבר הוא שם עברי חדש, וכנראה הוא קשור למילה ניב, מילה ודיבור, וגם פרי. המקור המדויק לא ברור, והשם נבנה כנראה מצליל שנשמע טוב. השם ניתן בעיקר לבנות.", [])
n("דיאן", "דיאן היא הצורה הצרפתית של דיאנה, שמה של אלת הציד והירח ברומא העתיקה. השם נפוץ בצרפתית ובאנגלית, ובאנגלית הוא נכתב גם דיאן. בעברית השם נשמע קצר ורך.", ["דיאנה"])
n("גון", "גון היא מילה עברית לצבע ולגוון, והיא קשורה למילים גוני וגוון. בעברית של היום משתמשים בה גם בתיאור של טון ושל צליל. כשם, גון מביא את הרעיון של עולם צבעוני.", ["גוני"])
n("דומיניק", "דומיניק הוא שם שבא מהמילה הלטינית דומיניקוס, של האדון. השם נפוץ בצרפתית ובשפות של אירופה, והוא ניתן גם לבנים וגם לבנות. ביום ראשון בלטינית נקרא דיאס דומיניקה, ומשם גם השם.", [])
n("ציונה", "ציונה הוא שם עברי שבא מהמילה ציון, אחד השמות של ירושלים ושל ארץ ישראל. השם היה נפוץ בימי היישוב ובשנים הראשונות של המדינה, כביטוי של אהבה לארץ. מאותה מילה בא גם השם נס ציונה.", ["ציון"])
n("עמי", "עמי הוא שם עברי שפירושו העם שלי. המילה עם מופיעה בתוך שמות עבריים רבים, כמו עמית, עמיאל ועמיחי. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["עמית"])
n("אלזה", "אלזה היא צורה גרמנית של אליזבת, שהיא הצורה האירופית של השם העברי אלישבע. השם היה נפוץ בגרמנית ובשפות הסקנדינביות. בשנים האחרונות הוא נעשה מוכר גם בזכות סרטים לילדים.", [])
n("גוליה", "גוליה הוא שם רוסי, צורת חיבה של יוליה, שבא מהשם הלטיני יוליוס. הכתיב עם האות ג מסמן את ההגייה הרוסית. השם הגיע לארץ עם העלייה מברית המועצות.", ["יוליה"])
n("פערי", "פערי הוא שם ביידיש, וכנראה הוא צורה של פערל, פנינה. ביידיש נכתבת התנועה באות ע. השם היה נפוץ בקהילות של מזרח אירופה, ומוכרות גם הצורות פעריל ופרלה.", ["פעריל"])
n("אודי", "אודי הוא צורת חיבה של אהוד, שבמסורת הוא אחד השופטים. השם אהוד קשור כנראה לשורש ה־ו־ד, הוד ותהילה. בעברית השם נשמע גם כמו המילה אודי, אוד בוער.", ["אהוד"])
n("קרלוס", "קרלוס הוא הצורה הספרדית והפורטוגזית של קרל, שם שבא מגרמנית עתיקה ופירושו אדם חופשי. השם נפוץ מאוד בשפה הספרדית ובאמריקה הלטינית. מאותו שם באים גם צ׳ארלס ושארל.", [])
n("לירום", "לירום הוא שם עברי חדש שבנוי משתי מילים, לי ורום, ופירושו הגובה שלי. המילה רום פירושה גובה ומקום נעלה. השם נשמע קרוב ללירם וללירון.", ["לירם"])
n("עקיבה", "עקיבה הוא כתיב של עקיבא, צורה ארמית של השם יעקב. השם מוכר בזכות רבי עקיבא, מגדולי חכמי המשנה, שחי בתקופת מרד בר כוכבא. הכתיב עם האות ה בסוף נפוץ פחות.", ["עקיבא"])
n("אמנון", "אמנון הוא שם מקראי מהשורש א־מ־ן, שממנו באות המילים אמונה ונאמנות. בתנ״ך אמנון הוא בנו הבכור של דוד המלך. בעברית החדשה השם היה נפוץ מאוד בשנות הארבעים והחמישים.", [])
n("אדי", "אדי הוא קיצור של שמות כמו אדוארד, אדריאן ואדמונד, והוא נפוץ באנגלית כשם בפני עצמו. בעברית המילה אדי פירושה גם אדים, לחות שעולה מהאדמה. השם קצר ופשוט.", [])
n("טים", "טים הוא קיצור של טימותי, שם שבא מהיוונית ופירושו מכבד את האל. באנגלית ובגרמנית טים הוא שם בפני עצמו. השם קצר ופשוט, ונוח במשפחות שחיות בין שתי שפות.", [])
n("ליפא", "ליפא הוא שם ביידיש, וכנראה הוא צורת חיבה של אליעזר, או של השם ליפמן. ביידיש שמות רבים מסתיימים באות א. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", [])
n("טאיה", "טאיה הוא שם חדש, וכנראה הוא צורה של תיאה, שם יווני שפירושו אלה. בשפות אחרות יש לשם צליל דומה ומקורות שונים. השם ניתן בעיקר לבנות.", ["טאי"])
n("מליא", "מליא היא מילה ארמית שפירושה מלאה. בארמית של התלמוד מופיע הביטוי מליא עלמא, העולם מלא. כשם, מליא מביא את הרעיון של שפע ושל מלאות.", [])
n("שירת", "שירת הוא שם עברי חדש שבא מהמילה שירה. בעברית הצורה שירת מופיעה בצירופים כמו שירת הים ושירת דבורה. השם ניתן בעיקר לבנות.", ["שירה"])
n("פבל", "פבל היא הצורה הרוסית והצ׳כית של פאולוס, שם לטיני שפירושו קטן. ברוסית ובאוקראינית השם נפוץ מאוד, ומוכרת גם צורת החיבה פאשה. השם הגיע לארץ עם העלייה מברית המועצות.", [])
n("ליבנת", "ליבנת הוא שם עברי חדש שקשור למילים לבנה ולובן. המילה לבנה מתארת את הירח, וליבנה היא גם שמו של עץ עם גזע לבן. השם ניתן בעיקר לבנות.", ["ליבנה"])
n("ערד", "ערד היא עיר עתיקה בנגב, שמלכה נלחם בבני ישראל במדבר, ועיר חדשה באותו שם נבנתה בשנות השישים. בתל ערד נמצא מקדש קטן מימי בית ראשון. כשם, ערד ניתן בעיקר לבנים.", [])
n("לטם", "לטם הוא שם עברי חדש, וכנראה הוא קשור למילה לוט, שרף ריחני שמוזכר בסיפור יוסף ובו מסחר של שיירות. מקור השם לא ברור, ויש שקושרים אותו גם לשיח הלוטם. השם ניתן בעיקר לבנות.", ["לוטם"])
n("טימור", "טימור הוא שם טורקי ומונגולי שפירושו ברזל. השם מוכר בזכות שליט ידוע מהמאה הארבע עשרה. בעברית הוא נשמע קרוב לתימור, שקשור לעץ התמר.", ["תימור"])
n("מיליה", "מיליה הוא שם חדש, וכנראה הוא צורה של אמיליה, שם לטיני. השם נשמע קרוב גם למילי ולמילה. השם ניתן בעיקר לבנות, והוא קצר ורך.", ["מילי"])
n("אושרה", "אושרה הוא שם עברי מהמילה אושר, שמחה ושלווה. מאותו שורש, א־ש־ר, באים גם השמות אשר, אושרי ואושרת. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["אושרת", "אושרית"])
n("אבירן", "אבירן הוא שם עברי חדש שבנוי משתי מילים, אבי ורן, ופירושו אבי הוא השיר שלי. המילה רן באה מהשורש ר־נ־ן, שירה ושמחה. השם נשמע קרוב לאבירם.", [])
n("עזריה", "עזריה הוא שם מקראי שבנוי מהמילה עזר ומהסיומת יה, ופירושו ה׳ עזר. עזריה הוא אחד ממלכי יהודה, שנקרא גם עוזיהו. מאותו שורש באים גם השמות עזרא ואליעזר.", ["עזרא", "עזריאל"])
n("טילא", "טילא הוא שם ביידיש, צורת חיבה של מטילדה או של אוטיליה. ביידיש שמות רבים מסתיימים באות א. השם היה נפוץ בקהילות של מזרח אירופה.", ["מאטיל"])
n("עטיא", "עטיא הוא שם עברי, וכנראה הוא קשור למילה עטרה, כתר וקישוט לראש. הסיומת א מזכירה את הארמית. השם נשמע קרוב לעטי ולעטרה.", ["עטי"])
n("ג'ונתן", "ג׳ונתן הוא הצורה האנגלית של יהונתן, שם מקראי שפירושו ה׳ נתן. במסורת יהונתן הוא בנו של שאול המלך וחברו הקרוב של דוד. באנגלית השם נפוץ מאוד, ומוכרת גם צורת החיבה ג׳ון.", ["יהונתן"])
n("פייגל", "פייגל הוא שם ביידיש, שבא מהמילה היידית פויגל, ציפור. ביידיש מוכרות גם הצורות פייגה ופיגא. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", ["פיגא", "פייגי"])
n("שי-יה", "שי־יה הוא שם עברי חדש שבנוי משתי מילים, שי ויה, ופירושו מתנה של ה׳. המילה שי היא מילה עתיקה למתנה. המקף מפריד בין שני חלקי השם.", ["שי-אל"])
n("לימור", "לימור הוא שם עברי חדש שבנוי משתי מילים, לי ומור, ופירושו יש לי מור. המור הוא שרף ריחני יקר, שהיה מוכר בעולם העתיק כבושם. השם היה נפוץ בארץ בשנות השבעים, ולימור הוא גם שמו של בעל חיים קטן ממדגסקר.", [])
n("פיליפ", "פיליפ הוא שם שבא מהיוונית, ובנוי משתי מילים, פילוס, אוהב, והיפוס, סוס, ופירושו אוהב סוסים. השם נפוץ בשפות רבות של אירופה. כמה מלכים בצרפת ובספרד נשאו את השם הזה.", [])
